import {
  partitionPoint
} from "./chunk-HOAIOEI7.js";

// src/tubeMap/warp.ts
var MAX_GAP_PX = 24;
var MAX_GAP_SHARE = 0.5;
var isReal = (c) => c.bp1 > c.bp0;
function referenceKnots(columns, bpToScreen) {
  const real = columns.filter(isReal);
  if (real.length === 0) {
    const first = columns[0];
    return first ? [{ tx: first.x0, sx: bpToScreen(first.bp0) }] : [];
  }
  const tx = [];
  const target = [];
  const gap = [];
  real.forEach((c, i) => {
    tx.push(c.x0, c.x1);
    target.push(bpToScreen(c.bp0), bpToScreen(c.bp1));
    gap.push(i === 0 ? 0 : Math.min(c.x0 - real[i - 1].x1, MAX_GAP_PX), 0);
  });
  const span = target.at(-1) - target[0];
  const demand = gap.reduce((a, b) => a + b, 0);
  const scale = demand > 0 ? Math.min(1, MAX_GAP_SHARE * span / demand) : 1;
  return spread(target, gap, scale).map((sx, k) => ({ tx: tx[k], sx }));
}
function spread(target, gap, scale) {
  const offset = [];
  let sum = 0;
  for (const g of gap) {
    sum += g * scale;
    offset.push(sum);
  }
  const blocks = [];
  target.forEach((t, k) => {
    let block = { mean: t - offset[k], n: 1 };
    let last = blocks.at(-1);
    while (last && last.mean >= block.mean) {
      blocks.pop();
      const n = last.n + block.n;
      block = { mean: (last.mean * last.n + block.mean * block.n) / n, n };
      last = blocks.at(-1);
    }
    blocks.push(block);
  });
  return blocks.flatMap((b) => Array(b.n).fill(b.mean)).map((q, k) => q + offset[k]);
}
function warpX(knots, tx) {
  const n = knots.length;
  if (n === 0) {
    return tx;
  }
  const first = knots[0];
  const last = knots[n - 1];
  if (tx <= first.tx) {
    return first.sx + (tx - first.tx);
  }
  if (tx >= last.tx) {
    return last.sx + (tx - last.tx);
  }
  const hi = 1 + partitionPoint(n - 2, (i) => knots[i + 1].tx <= tx);
  const a = knots[hi - 1];
  const b = knots[hi];
  const span = b.tx - a.tx;
  return span > 0 ? a.sx + (tx - a.tx) / span * (b.sx - a.sx) : a.sx;
}

export {
  MAX_GAP_PX,
  referenceKnots,
  warpX
};
