// src/el.ts
function el(tag, attrs = {}, ...children) {
  return {
    tag,
    attrs,
    children: children.filter((c) => !!c || c === "")
  };
}
function escapeText(s) {
  return s.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}
function escapeAttr(s) {
  return escapeText(s).replaceAll('"', "&quot;");
}
function serializeEl(node) {
  if (typeof node === "string") {
    return escapeText(node);
  }
  const attrs = Object.entries(node.attrs).filter(([, v]) => v !== void 0).map(([k, v]) => ` ${k}="${escapeAttr(String(v))}"`).join("");
  return `<${node.tag}${attrs}>${node.children.map(serializeEl).join("")}</${node.tag}>`;
}

export {
  el,
  escapeAttr,
  serializeEl
};
