import {
  SATURATED_PATH_COUNT
} from "./chunk-FX4RDMDN.js";
import {
  formatBp
} from "./chunk-ENBFQH7Y.js";

// src/bubbles/classifyBubble.ts
var REPEAT_GROWTH = 10;
function coveringRepeat(b, repeats) {
  const span = b.end - b.start;
  const growth = b.longestAlleleLength - b.shortestAlleleLength;
  return repeats.find(
    (r) => growth <= REPEAT_GROWTH * (r.end - r.start) && (span === 0 ? r.start <= b.start && b.start <= r.end : Math.min(b.end, r.end) - Math.max(b.start, r.start) >= span / 2)
  );
}
var SUPERBUBBLE_SEGMENTS = 40;
function formatBpRange(shortest, longest) {
  const low = formatBp(shortest);
  const high = formatBp(longest);
  const unit = high.slice(high.indexOf(" "));
  return low.endsWith(unit) ? `${low.slice(0, -unit.length)}\u2013${high}` : `${low}\u2013${high}`;
}
function routes(count) {
  if (count >= SATURATED_PATH_COUNT) {
    return "\u22652.1B routes";
  }
  if (count >= 1e5) {
    return `${(count / 1e3).toFixed(0)}k routes`;
  }
  return `${count} routes`;
}
function classifyBubble(b, repeats = []) {
  const c = classifyShape(b, repeats);
  return b.partial ? { ...c, label: `${c.label}, partial` } : c;
}
function classifyShape(b, repeats) {
  const refSpan = b.end - b.start;
  const {
    shortestAlleleLength: shortest,
    longestAlleleLength: longest,
    pathCount,
    segmentCount,
    inversion
  } = b;
  const range = formatBpRange(shortest, longest);
  if (segmentCount >= SUPERBUBBLE_SEGMENTS) {
    return {
      kind: "superbubble",
      label: `${range} superbubble, ${segmentCount} segments, ${routes(pathCount)}${inversion ? ", inv" : ""}`
    };
  }
  if (inversion) {
    return { kind: "inversion", label: `${formatBp(longest)} inv` };
  }
  if (b.offReference) {
    return shortest === longest ? sameLength(shortest) : { kind: "complex", label: `${range}, ${routes(pathCount)}` };
  }
  const repeat = longest !== shortest ? coveringRepeat(b, repeats) : void 0;
  if (repeat) {
    const name = repeat.name ? ` (${repeat.name})` : "";
    return {
      kind: "repeat",
      label: `${range} repeat array${name}, ${routes(pathCount)}`
    };
  }
  const alleles = pathCount > 2 ? `, ${pathCount} alleles` : "";
  if (shortest === longest && shortest === refSpan) {
    return sameLength(refSpan);
  }
  if (refSpan === 0 || shortest === refSpan) {
    return {
      kind: "insertion",
      label: `\u2264${formatBp(longest - refSpan)} ins${alleles}`
    };
  }
  if (longest === refSpan) {
    return {
      kind: "deletion",
      label: `${formatBp(refSpan - shortest)} del${alleles}`
    };
  }
  return {
    kind: "complex",
    label: `${formatBp(refSpan)} ref \u2192 ${range}, ${pathCount} alleles`
  };
}
function sameLength(bp) {
  return bp <= 1 ? { kind: "snp", label: "SNP" } : { kind: "substitution", label: `${formatBp(bp)} sub` };
}
var BUBBLE_KIND_COLORS = {
  snp: "#5b6b7a",
  substitution: "#5b6b7a",
  insertion: "#2f8fd6",
  deletion: "#c94040",
  inversion: "#e07b00",
  repeat: "#8e3fbf",
  superbubble: "#8e3fbf",
  complex: "#8e3fbf"
};
var BUBBLE_KIND_NAMES = {
  snp: "SNP",
  substitution: "substitution",
  insertion: "insertion",
  deletion: "deletion",
  inversion: "inversion",
  repeat: "repeat array",
  superbubble: "superbubble",
  complex: "site"
};
function bubbleSegmentIds(b) {
  return b.segments.split(",").filter(Boolean);
}

export {
  classifyBubble,
  BUBBLE_KIND_COLORS,
  BUBBLE_KIND_NAMES,
  bubbleSegmentIds
};
