import {
  walkRowRuns,
  walkRowsOf
} from "./chunk-G72GQNM2.js";

// src/layout/walkRows.ts
function filterSamples(rows, samples) {
  return samples ? rows.filter((r) => samples.includes(r.sample)).sort(
    (a, b) => samples.indexOf(a.sample) - samples.indexOf(b.sample) || a.label.localeCompare(b.label)
  ) : rows;
}
function walkRows(graph, region, unit, o = {}) {
  const runs = walkRowRuns(graph, region, o);
  return runs && walkRowsOf(runs, unit);
}

export {
  filterSamples,
  walkRows
};
