// src/tubeMap/connectors.ts
function tubeMapConnectors(boxes, bpToScreen, tubeToScreen, width) {
  const out = [];
  for (const box of boxes) {
    const bottom0 = tubeToScreen(box.x0);
    const bottom1 = tubeToScreen(box.x1);
    if (bottom1 >= 0 && bottom0 <= width) {
      out.push({
        node: box.name,
        top0: bpToScreen(box.bp0),
        top1: bpToScreen(box.bp1),
        bottom0,
        bottom1
      });
    }
  }
  return out;
}
var HIT_SLOP_PX = 3;
function connectorAt(connectors, zoneBottom, sx, sy) {
  if (zoneBottom <= 0 || sy < 0 || sy > zoneBottom) {
    return void 0;
  }
  const t = sy / zoneBottom;
  let hit;
  let best = HIT_SLOP_PX;
  for (const c of connectors) {
    const a = c.top0 + (c.bottom0 - c.top0) * t;
    const b = c.top1 + (c.bottom1 - c.top1) * t;
    const dist = Math.max(0, Math.min(a, b) - sx, sx - Math.max(a, b));
    if (dist < best) {
      best = dist;
      hit = c.node;
    }
  }
  return hit;
}
function band(ctx, c, bottom) {
  ctx.moveTo(c.top0, 0);
  ctx.lineTo(c.top1, 0);
  ctx.lineTo(c.bottom1, bottom);
  ctx.lineTo(c.bottom0, bottom);
  ctx.closePath();
}
function sides(ctx, c, bottom) {
  ctx.moveTo(c.top0, 0);
  ctx.lineTo(c.bottom0, bottom);
  ctx.moveTo(c.top1, 0);
  ctx.lineTo(c.bottom1, bottom);
}
function drawTubeMapConnectors(ctx, connectors, bottom, {
  highlightNode,
  darkMode
}) {
  if (bottom <= 0 || connectors.length === 0) {
    return;
  }
  const ink = darkMode ? "255,255,255" : "0,0,0";
  ctx.beginPath();
  for (const c of connectors) {
    band(ctx, c, bottom);
  }
  ctx.fillStyle = `rgba(${ink},0.07)`;
  ctx.fill();
  ctx.beginPath();
  for (const c of connectors) {
    sides(ctx, c, bottom);
  }
  ctx.strokeStyle = `rgba(${ink},0.35)`;
  ctx.lineWidth = 0.5;
  ctx.stroke();
  drawLitConnector(ctx, connectors, bottom, highlightNode);
}
function drawLitConnector(ctx, connectors, bottom, node) {
  const lit = bottom > 0 && node ? connectors.find((c) => c.node === node) : void 0;
  if (lit) {
    ctx.beginPath();
    band(ctx, lit, bottom);
    ctx.fillStyle = "rgba(255,192,203,0.5)";
    ctx.fill();
    ctx.beginPath();
    sides(ctx, lit, bottom);
    ctx.strokeStyle = "#ff0000";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

