import {
  nodesUnderBox
} from "./chunk-QWLCHMNS.js";
import {
  graphLabels,
  rowLabelBox
} from "./chunk-ENBFQH7Y.js";
import {
  LABEL_CHAR_PX,
  LABEL_PAD,
  LABEL_PX,
  occupancy,
  placeLabels
} from "./chunk-AB35TJST.js";

// src/labelLayout.ts
var HALO_FACTOR = 3.4;
var LEGEND_INSET_PX = 6;
var GENE_PIN_DROP_PX = 18;
var GENE_STACK = 2;
var BUBBLE_STACK = 3;
var TOPMOST_BASELINE = LABEL_PX + LABEL_PAD;
function geneCoverageNote(pin) {
  const length = pin.gene.end - pin.gene.start;
  if (pin.covered >= 0.98) {
    return void 0;
  }
  const [per, unit] = length >= 999500 ? [1e6, "Mb"] : length >= 1e3 ? [1e3, "kb"] : [1, "bp"];
  const amount = (bp) => +(bp / per).toFixed(per === 1 ? 0 : 1);
  return `${amount(pin.covered * length)} of ${amount(length)} ${unit}`;
}
function geneLabelCandidates(pins, screen, contigThickness, nodesUnder) {
  const ink = contigThickness / 2;
  return byExtent(pins, (pin) => pin.gene.end - pin.gene.start).map((pin) => {
    const { x, y } = screen(pin.at);
    const note = geneCoverageNote(pin);
    return {
      item: pin,
      x,
      y: y + contigThickness + GENE_PIN_DROP_PX,
      text: note ? `${pin.gene.name} \xB7 ${note}` : pin.gene.name,
      fallback: note ? `${pin.gene.name} \u2026` : void 0,
      stack: GENE_STACK,
      fits: (box) => [
        ...nodesUnder({
          x0: box.x0 - ink,
          x1: box.x1 + ink,
          y0: box.y0 - ink,
          y1: box.y1 + ink
        })
      ].every((id) => pin.nodeIds.has(id))
    };
  });
}
function byExtent(items, extent) {
  return [...items].sort((a, b) => extent(b) - extent(a));
}
function layoutLabels(m) {
  const { paneWidth: width, canvasHeight: height, translateX, translateY } = m;
  const { scaleX, scaleY } = m.axisScale;
  const frame = { width, height };
  const screen = (p) => ({
    x: p.x * scaleX + translateX,
    y: p.y * scaleY + translateY
  });
  const reserved = m.drawnRowLabels.map(
    ({ label, y }) => rowLabelBox(label, y * scaleY + translateY)
  );
  const stripPx = m.referenceStripZonePx ?? 0;
  if (stripPx > 0) {
    reserved.push({ x0: 0, x1: width, y0: 0, y1: stripPx });
  }
  if (m.legendSize.width > 0) {
    reserved.push({
      x0: width - LEGEND_INSET_PX - m.legendSize.width,
      x1: width,
      y0: 0,
      y1: stripPx + LEGEND_INSET_PX + m.legendSize.height
    });
  }
  if (m.poppedFrom) {
    reserved.push({
      x0: 0,
      x1: 60 + m.poppedFrom.label.length * LABEL_CHAR_PX * 1.2,
      y0: 0,
      y1: 44
    });
  }
  const take = occupancy(frame, reserved);
  const onRows = m.drawnRowLabels.length > 0;
  const rowsTop = onRows ? Math.min(...m.drawnRowLabels.map((r) => r.y)) : Infinity;
  const halo = m.contigThickness * HALO_FACTOR;
  const above = (h, gap) => {
    const { x, y } = screen({
      x: h.labelAt.x,
      y: Math.min(h.labelAt.y, rowsTop)
    });
    const baseline = y - halo / 2 - gap;
    return { x, y: onRows ? Math.max(baseline, TOPMOST_BASELINE) : baseline };
  };
  const byBubble = byExtent(
    m.bubbleHalos.filter((h) => !h.tick),
    (h) => h.whole ? -1 : h.members
  );
  const bubbles = placeLabels(
    byBubble.map((h) => ({
      item: h,
      ...above(h, 6),
      text: h.label,
      // `0 bp–11 kb superbubble` where `…, 1198 segments, 5 routes` does not fit
      fallback: h.label.includes(",") ? h.label.split(",")[0] : void 0,
      stack: BUBBLE_STACK
    })),
    frame,
    take
  );
  const ticks = m.bubbleHalos.filter((h) => h.tick).map((h) => ({ item: h, ...above(h, 2) })).filter((t) => t.x >= 0 && t.x <= width && t.y >= 0 && t.y <= height);
  const genes = placeLabels(
    geneLabelCandidates(
      m.genePins,
      screen,
      m.contigThickness,
      nodesUnderBox(
        m.nodePositions ?? {},
        { scaleX, scaleY, translateX, translateY },
        m.positionsVersion
      )
    ),
    frame,
    take
  );
  const sizes = m.nodePositions && m.labelsNodeSizes ? graphLabels({
    nodePositions: m.nodePositions,
    nodeLengths: m.nodeLengths,
    deletions: m.deletions,
    deletionRoutes: m.deletionRoutes,
    stranded: m.stranded,
    alleleDeletions: m.alleleDeletions,
    axis: m.axisScale,
    translateX,
    translateY,
    width,
    height,
    version: m.positionsVersion,
    take
  }) : [];
  return {
    bubbles,
    ticks,
    genes,
    sizes
  };
}

export {
  HALO_FACTOR,
  LEGEND_INSET_PX,
  geneCoverageNote,
  geneLabelCandidates,
  layoutLabels
};
