// src/renderer/canvas.ts
var MAX_DPR = 2;
var MAX_CANVAS_DIM_PX = 8192;
function getDpr(width = 0, height = 0) {
  const dpr = typeof devicePixelRatio === "undefined" ? 1 : Math.min(devicePixelRatio, MAX_DPR);
  return Math.min(dpr, MAX_CANVAS_DIM_PX / Math.max(width, height, 1));
}
function syncCanvasSize(canvas, width, height) {
  const dpr = getDpr(width, height);
  const pw = Math.round(width * dpr);
  const ph = Math.round(height * dpr);
  if (canvas.width !== pw || canvas.height !== ph) {
    canvas.width = pw;
    canvas.height = ph;
  }
  const cssWidth = `${width}px`;
  const cssHeight = `${height}px`;
  if (canvas.style.width !== cssWidth) {
    canvas.style.width = cssWidth;
  }
  if (canvas.style.height !== cssHeight) {
    canvas.style.height = cssHeight;
  }
  return dpr;
}

export {
  MAX_DPR,
  MAX_CANVAS_DIM_PX,
  getDpr,
  syncCanvasSize
};
